export type HotFileWriteOwnerId = string;

export interface HotFileWriteOwnerClaim {
  readonly path: string;
  readonly owner: HotFileWriteOwnerId;
  readonly token: string;
  readonly reentrant: boolean;
}

export interface HotFileWriteOwnerConflict {
  readonly conflict: true;
  readonly path: string;
  readonly holder: HotFileWriteOwnerId;
  readonly reentrant: false;
}

export type HotFileWriteOwnerClaimResult =
  | HotFileWriteOwnerClaim
  | HotFileWriteOwnerConflict;

export interface HotFileWriteOwnerReleaseResult {
  readonly released: boolean;
  readonly path: string;
  readonly owner?: HotFileWriteOwnerId;
}

export interface HotFileWriteOwnerOptions {
  /** Injectable for deterministic callers and tests. */
  readonly tokenFactory?: () => string;
  /**
   * Existing file-mutation lease kernel. `runExclusive` must provide the
   * repository's FIFO, capacity and timeout behaviour; this module does not
   * create a scheduler of its own.
   */
  readonly lease?: HotFileWriteOwnerLeaseKernel;
}

export interface HotFileWriteOwnerLeaseKernel {
  runExclusive<T>(path: string, operation: () => T | Promise<T>): T | Promise<T>;
}

interface ActiveClaim {
  readonly owner: HotFileWriteOwnerId;
  readonly token: string;
}

function defaultTokenFactory(): string {
  const cryptoApi = globalThis.crypto;
  if (cryptoApi && typeof cryptoApi.randomUUID === "function") {
    return cryptoApi.randomUUID();
  }
  return `hot-file-write-owner-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function normalizePath(path: string): string {
  if (typeof path !== "string" || path.length === 0) {
    throw new TypeError("path must be a non-empty string");
  }
  return path;
}

function normalizeOwner(owner: HotFileWriteOwnerId): HotFileWriteOwnerId {
  if (typeof owner !== "string" || owner.length === 0) {
    throw new TypeError("owner must be a non-empty string");
  }
  return owner;
}

/**
 * Adds verifiable ownership to an existing per-file mutation lease.
 *
 * Claims are compare-and-swap operations: a different owner receives an
 * explicit conflict, while a claim by the current owner is idempotent. The
 * owner record is removed only by the matching token, so failed writes can
 * safely roll their claim back without releasing somebody else's claim.
 */
export class HotFileWriteOwner {
  readonly #claims = new Map<string, ActiveClaim>();
  readonly #tokenFactory: () => string;
  readonly #lease?: HotFileWriteOwnerLeaseKernel;

  constructor(options: HotFileWriteOwnerOptions = {}) {
    this.#tokenFactory = options.tokenFactory ?? defaultTokenFactory;
    this.#lease = options.lease;
  }

  claim(
    path: string,
    owner: HotFileWriteOwnerId,
  ): HotFileWriteOwnerClaimResult {
    const normalizedPath = normalizePath(path);
    const normalizedOwner = normalizeOwner(owner);
    const current = this.#claims.get(normalizedPath);

    if (current) {
      if (current.owner === normalizedOwner) {
        return {
          path: normalizedPath,
          owner: normalizedOwner,
          token: current.token,
          reentrant: true,
        };
      }
      return {
        conflict: true,
        path: normalizedPath,
        holder: current.owner,
        reentrant: false,
      };
    }

    const token = this.#tokenFactory();
    this.#claims.set(normalizedPath, { owner: normalizedOwner, token });
    return {
      path: normalizedPath,
      owner: normalizedOwner,
      token,
      reentrant: false,
    };
  }

  release(
    path: string,
    owner: HotFileWriteOwnerId,
    token: string,
  ): HotFileWriteOwnerReleaseResult {
    const normalizedPath = normalizePath(path);
    const normalizedOwner = normalizeOwner(owner);
    const current = this.#claims.get(normalizedPath);

    if (
      !current ||
      current.owner !== normalizedOwner ||
      current.token !== token
    ) {
      return { released: false, path: normalizedPath, owner: normalizedOwner };
    }

    this.#claims.delete(normalizedPath);
    return { released: true, path: normalizedPath, owner: normalizedOwner };
  }

  /** Roll back a claim using the same token used to acquire it. */
  rollback(
    path: string,
    owner: HotFileWriteOwnerId,
    token: string,
  ): HotFileWriteOwnerReleaseResult {
    return this.release(path, owner, token);
  }

  holder(path: string): HotFileWriteOwnerId | null {
    return this.#claims.get(normalizePath(path))?.owner ?? null;
  }

  /**
   * Executes a write in the supplied existing mutation lease. Ownership is
   * acquired inside the lease and is always released, including on failure.
   */
  async runExclusive<T>(
    path: string,
    owner: HotFileWriteOwnerId,
    operation: (claim: HotFileWriteOwnerClaim) => T | Promise<T>,
  ): Promise<T> {
    const normalizedPath = normalizePath(path);
    const normalizedOwner = normalizeOwner(owner);
    const invoke = async (): Promise<T> => {
      const result = this.claim(normalizedPath, normalizedOwner);
      if ("conflict" in result) {
        throw new HotFileWriteOwnerConflictError(result);
      }
      try {
        return await operation(result);
      } finally {
        this.release(normalizedPath, normalizedOwner, result.token);
      }
    };

    if (!this.#lease) {
      throw new Error("hot-file-write-owner requires the existing fileMutation lease kernel");
    }
    return await this.#lease.runExclusive(normalizedPath, invoke);
  }
}

export class HotFileWriteOwnerConflictError extends Error {
  readonly conflict: HotFileWriteOwnerConflict;

  constructor(conflict: HotFileWriteOwnerConflict) {
    super(`hot file write ownership conflict for ${conflict.path}: holder is ${conflict.holder}`);
    this.name = "HotFileWriteOwnerConflictError";
    this.conflict = conflict;
  }
}

export function claimHotFileWriteOwner(
  owner: HotFileWriteOwner,
  path: string,
  claimOwner: HotFileWriteOwnerId,
): HotFileWriteOwnerClaimResult {
  return owner.claim(path, claimOwner);
}

export function releaseHotFileWriteOwner(
  owner: HotFileWriteOwner,
  path: string,
  claimOwner: HotFileWriteOwnerId,
  token: string,
): HotFileWriteOwnerReleaseResult {
  return owner.release(path, claimOwner, token);
}

export function rollbackHotFileWriteOwner(
  owner: HotFileWriteOwner,
  path: string,
  claimOwner: HotFileWriteOwnerId,
  token: string,
): HotFileWriteOwnerReleaseResult {
  return owner.rollback(path, claimOwner, token);
}

